const items = $input.all();
const ttsItems = $('Build TTS Text').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const d = (ttsItems[i] && ttsItems[i].json) ? ttsItems[i].json : (item.json || {});

  const connStr = $env.AZURE_STORAGE_CONNECTION_STRING || '';
  const accountName = (connStr.match(/AccountName=([^;]+)/) || [])[1] || '';
  const accountKey  = (connStr.match(/AccountKey=([^;]+)/)  || [])[1] || '';
  const container   = $env.AZURE_BLOB_CONTAINER || 'tiktok-videos';
  const blobName    = d.blob_name;
  const binProp     = item.binary && item.binary.data;
  const contentLength = binProp ? (binProp.bytes || 0).toString() : '0';
  const contentType = 'audio/mpeg';
  const msDate      = new Date().toUTCString();
  const canonHeaders  = ['x-ms-blob-type:BlockBlob', `x-ms-date:${msDate}`, 'x-ms-version:2020-04-08'].join('\n');
  const canonResource = `/${accountName}/${container}/${blobName}`;
  const stringToSign  = ['PUT','','',contentLength,'',contentType,'','','','','','',canonHeaders,canonResource].join('\n');

  const keyBuf = Buffer.from(accountKey, 'base64');
  const sigBuf = hmacSha256(keyBuf, Buffer.from(stringToSign, 'utf8'));
  const signature = sigBuf.toString('base64');

  results.push({
    json: {
      ...d,
      azure_url: `https://${accountName}.blob.core.windows.net/${container}/${blobName}`,
      azure_auth: `SharedKey ${accountName}:${signature}`,
      azure_date: msDate,
      azure_content_type: contentType,
      azure_content_length: contentLength
    },
    binary: item.binary
  });
}

return results;

